import{_ as a,c as r,o as t,a3 as o}from"./chunks/framework.Dk6sf0Ip.js";const h=JSON.parse('{"title":"Paso a Paso: Ingreso de Cubiertas al Stock","description":"","frontmatter":{},"headers":[],"relativePath":"CasosParticulares/cubiertas/remitoingresocubiertas.md","filePath":"CasosParticulares/cubiertas/remitoingresocubiertas.md","lastUpdated":1759323946000}'),l={name:"CasosParticulares/cubiertas/remitoingresocubiertas.md"};function i(n,e,s,c,d,u){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="paso-a-paso-ingreso-de-cubiertas-al-stock" tabindex="-1">Paso a Paso: Ingreso de Cubiertas al Stock <a class="header-anchor" href="#paso-a-paso-ingreso-de-cubiertas-al-stock" aria-label="Permalink to &quot;Paso a Paso: Ingreso de Cubiertas al Stock&quot;">​</a></h1><p>Este es el proceso para llegar desde la pantalla principal de &quot;Remito ingreso&quot; a la adición del detalle del artículo (cubierta) en el depósito correcto.</p><h2 id="_1-iniciar-el-remito-de-ingreso-pantalla-principal" tabindex="-1">1. Iniciar el Remito de Ingreso (Pantalla Principal) <a class="header-anchor" href="#_1-iniciar-el-remito-de-ingreso-pantalla-principal" aria-label="Permalink to &quot;1. Iniciar el Remito de Ingreso (Pantalla Principal)&quot;">​</a></h2><p>Se encuentra en <strong><em>ALMACEN/STOCK</em></strong> dentro de esta la opcion de <strong>&quot;Remito ingreso&quot;</strong></p><h3 id="_15-4-06-remito-total-suma" tabindex="-1">15.4.06 Remito total (Suma) <a class="header-anchor" href="#_15-4-06-remito-total-suma" aria-label="Permalink to &quot;15.4.06 Remito total (Suma)&quot;">​</a></h3><h4 id="_1-revisar-completar-encabezado" tabindex="-1"><strong>1. Revisar/Completar Encabezado:</strong> <a class="header-anchor" href="#_1-revisar-completar-encabezado" aria-label="Permalink to &quot;**1. Revisar/Completar Encabezado:**&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nombre</th><th>Que ingresar</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Es el número del remito, generado automáticamente.</td></tr><tr><td><code>Fecha</code></td><td>Ingresar la fecha la cual se ingresa</td></tr><tr><td><code>Referencia</code></td><td>Se completa la razón del ingreso (ej: <strong>COMPRA DE NEUMATICOS</strong>)</td></tr><tr><td><code>Responsable</code></td><td>Se selecciona el vendedor o responsable (si aplica).</td></tr><tr><td><code>Opcional</code></td><td>SELECCIONAR ARCHIVO PARA ADJUNTAR <em>(si tienes la factura o documento de soporte)</em></td></tr></tbody></table><h4 id="_2-ir-al-detalle" tabindex="-1">2. <strong>Ir al Detalle:</strong> <a class="header-anchor" href="#_2-ir-al-detalle" aria-label="Permalink to &quot;2. **Ir al Detalle:**&quot;">​</a></h4><p>En la sección &quot;Detalle&quot;, haz clic en el botón azul <strong>AGREGAR</strong> ubicado en la parte inferior izquierda.</p><h2 id="_2-agregar-la-actividad-detalle-del-ingreso" tabindex="-1">2. Agregar la Actividad (Detalle del Ingreso) <a class="header-anchor" href="#_2-agregar-la-actividad-detalle-del-ingreso" aria-label="Permalink to &quot;2. Agregar la Actividad (Detalle del Ingreso)&quot;">​</a></h2><p>Al hacer clic en <strong>AGREGAR</strong>, se abrirá un ventana con titulo <strong>&quot;Agregar actividad&quot;</strong></p><h4 id="_1-buscar-seleccionar-el-articulo-cubierta" tabindex="-1">1. <strong>Buscar/Seleccionar el Artículo (Cubierta):</strong> <a class="header-anchor" href="#_1-buscar-seleccionar-el-articulo-cubierta" aria-label="Permalink to &quot;1. **Buscar/Seleccionar el Artículo (Cubierta):**&quot;">​</a></h4><ul><li><p>En el campo <strong>&quot;Artículo Deposito Id&quot;</strong>, comienza a escribir el código o la descripción de la cubierta que está ingresando.</p></li><li><p>El sistema te pedirá un <strong>mínimo de 2 caracteres</strong> para habilitar el filtrado. ○ <strong>Selecciona la cubierta</strong> de la lista que aparecerá.</p></li></ul><h4 id="_2-crear-el-articulo-si-no-existe" tabindex="-1">2. <strong>Crear el Artículo (Si No Existe):</strong> <a class="header-anchor" href="#_2-crear-el-articulo-si-no-existe" aria-label="Permalink to &quot;2. **Crear el Artículo (Si No Existe):**&quot;">​</a></h4><ul><li>Si la cubierta no existe en el sistema, haz clic en el símbolo de <strong>más (+)</strong> ubicado a la derecha del campo de búsqueda. Esto abrirá un formulario para crear un nuevo artículo <strong>-&gt;</strong> <a href="./crearcuiertas.html">Ver como hacerlo</a></li></ul><h4 id="_3-seleccionar-el-deposito-de-ingreso" tabindex="-1">3. <strong>Seleccionar el Depósito de Ingreso:</strong> <a class="header-anchor" href="#_3-seleccionar-el-deposito-de-ingreso" aria-label="Permalink to &quot;3. **Seleccionar el Depósito de Ingreso:**&quot;">​</a></h4><ul><li>Una vez que el artículo (cubierta) ha sido seleccionado, a la <strong>derecha</strong> del campo (junto a la lupa ρ y el signo +), el sistema te permitirá elegir la ubicación de ingreso.</li><li><strong>Asegúrate de seleccionar el depósito denominado &quot;CUBIERTAS&quot;</strong> (o el depósito específico para este tipo de artículo).</li></ul><h2 id="_3-finalizar-el-ingreso-del-detalle" tabindex="-1">3. Finalizar el Ingreso del Detalle <a class="header-anchor" href="#_3-finalizar-el-ingreso-del-detalle" aria-label="Permalink to &quot;3. Finalizar el Ingreso del Detalle&quot;">​</a></h2><h4 id="_1-guardar-el-detalle" tabindex="-1">1. <strong>Guardar el Detalle:</strong> <a class="header-anchor" href="#_1-guardar-el-detalle" aria-label="Permalink to &quot;1. **Guardar el Detalle:**&quot;">​</a></h4><ul><li>Haz clic en el botón azul <strong>GUARDAR</strong> en la ventana &quot;Agregar actividad&quot;. Esto cargará la línea de la cubierta en el &quot;Detalle&quot; del remito principal.</li></ul><h4 id="_2-agregar-mas-articulos" tabindex="-1">2. <strong>Agregar Más Artículos:</strong> <a class="header-anchor" href="#_2-agregar-mas-articulos" aria-label="Permalink to &quot;2. **Agregar Más Artículos:**&quot;">​</a></h4><ul><li>Si el remito trae más artículos, repite el <strong>Paso 2</strong> haciendo clic nuevamente en <strong>AGREGAR</strong> en la pantalla principal.</li></ul><h4 id="_3-finalizar-el-remito" tabindex="-1">3. <strong>Finalizar el Remito:</strong> <a class="header-anchor" href="#_3-finalizar-el-remito" aria-label="Permalink to &quot;3. **Finalizar el Remito:**&quot;">​</a></h4><ul><li>Una vez que todos los detalles estén cargados, haz clic en el botón azul <strong>GUARDAR</strong> en la parte superior derecha de la pantalla principal del <strong>&quot;Remito ingreso&quot;</strong> para consolidar y guardar todo el movimiento de stock.</li></ul>',24)]))}const p=a(l,[["render",i]]);export{h as __pageData,p as default};
